private func observeDormantShell(_ app: XCUIApplication, baseline: [String: Any]) async throws -> [String: Any] {
    element("host-counter-button", app).tap()
    var value = try await wait(app, "The native shell must respond while Godot is dormant.") {
        self.number("hostCounter", $0) == self.number("hostCounter", baseline) + 1
    }
    let minimum = max(0.8, decimal("audioObservationMinimumSeconds", native(baseline)))
    var observed = 0
    repeat {
        let previousPoll = number("pollCount", value)
        value = try await wait(app, "Observe another real native-shell sample.") { self.number("pollCount", $0) > previousPoll }
        try assertDormant(value)
        assertNoDormantWork(baseline, value)
        observed += 1
    } while observed < 2 || decimal("observedUptime", value) - decimal("observedUptime", baseline) < minimum
    attach(["before": baseline, "after": value, "samples": observed], "Measured dormant shell interval")
    return value

private func wait(_ app: XCUIApplication, _ message: String, timeout: TimeInterval = 15,
                  predicate: ([String: Any]) -> Bool) async throws -> [String: Any] {
    let startedAt = ProcessInfo.processInfo.systemUptime
    let deadline = Date().addingTimeInterval(timeout)
    var lastRejectedMeasurements: [String: Any] = [:]
    while Date() < deadline {
        let value = metrics(app)
        if app.state == .notRunning || !(value["failure"] as? String ?? "").isEmpty || flag("quarantined", native(value)) || native(value)["state"] as? String == "failed" {
            capture("Actual retained owner failure", app)
            XCTFail("The retained owner or native application failed.")
            throw Failure.native
        }
        if predicate(value) { return value }
        lastRejectedMeasurements = value
        try await Task.sleep(nanoseconds: 150_000_000)
    }
    // Screenshot capture can wait on the app and observe a later frame.
    // Keep the rejected value before requesting any further app work.
    attach(["timeoutSeconds": timeout,
            "elapsedSeconds": ProcessInfo.processInfo.systemUptime - startedAt,
            "measurements": lastRejectedMeasurements], "Last rejected retained wait observation")
    capture("Failed retained observation", app)
    XCTFail(message)
    throw Failure.timeout

func _viewport_frame_signature() -> Array:
	var signature: Array = [_viewport.size, _viewport.view_count, _stage.size,
		_camera.get_camera_transform(), _camera.get_camera_projection()]
	# Sample every card through the final Tween pose, including covered cards that
	# have no hit binding. State changes separately invalidate materials and ornaments.
	for card in _cards.get_children():
		signature.append(card.get_instance_id())
		signature.append(card.global_transform)
		signature.append(card.is_visible_in_tree())
	return signature


func _request_target_update() -> void:
	_viewport_dirty = true
	set_process(true)


func _resize() -> void:
	redraw_requested.emit()

func _run() -> void:
	if not _output.is_absolute_path() or not _fixtures.is_absolute_path():
		push_error("Absolute --check-output and --check-fixtures paths are required.")
		quit(1)
		return
	root.size = Vector2i(390, 844)
	for mode in ["2d", "3d"]:
		await _ordinary_intents(mode)
		await _pending_then_refresh(mode, true)
		await _pending_then_refresh(mode, false)
		for cancellation in ["host_background", "window_background", "close", "failure", "removal"]:
			await _cancel_pending(mode, cancellation)
	RenderingServer.render_loop_enabled = _initial_render_loop
	var report := {"result": "passed" if _failures == 0 else "failed", "checks": _checks,
		"godotVersion": Engine.get_version_info().string,
		"renderingMethod": RenderingServer.get_current_rendering_method(),
		"limitations": "Actual desktop scenes and frame counters; no Android JNI, EGL scheduling deadline or host authority acceptance is simulated."}
	DirAccess.make_dir_recursive_absolute(_output)
	FileAccess.open(_output.path_join("report.json"), FileAccess.WRITE).store_string(JSON.stringify(report, "\t"))
	print("Terminal return rendering checks: %d passed, %d failed." % [_checks.size() - _failures, _failures])
